import{_ as e}from"./chunks/led-battery-levels.BJDA0Ncv.js";import{_ as a}from"./chunks/led-charging.B18WnYb9.js";import{af as r,z as o,J as s,ab as i}from"./chunks/framework.C1QHhBQn.js";const m=JSON.parse('{"title":"Pro3 LED indicators","description":"","frontmatter":{"aside":true},"headers":[],"relativePath":"guides/pro3-leds.md","filePath":"guides/pro3-leds.md"}'),n={name:"guides/pro3-leds.md"};function h(d,t,l,c,p,g){return o(),s("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794235425000"},[...t[0]||(t[0]=[i('<h1 id="pro3-led-indicators" tabindex="-1">Pro3 LED indicators <a class="header-anchor" href="#pro3-led-indicators" aria-label="Permalink to &quot;Pro3 LED indicators&quot;">​</a></h1><p>This guide covers the four orange indicators on <strong>Pro3 (PR3), hardware revisions 02–04</strong>, with the standard firmware display. The diagrams illustrate the patterns, not the physical orientation of the case.</p><p>Looking for the older six-indicator Pro? Use <a href="/docs/pr/40/guides/tracker-leds">ProN/PR2 LED guidance</a> instead. See the <a href="/docs/pr/40/devices/pro/pro3">Pro3 device page</a> for the generation comparison.</p><h2 id="what-the-lights-show" tabindex="-1">What the lights show <a class="header-anchor" href="#what-the-lights-show" aria-label="Permalink to &quot;What the lights show&quot;">​</a></h2><p>Pro3 hardware revisions 02–04 have four orange indicators. They show battery status and charging progress, and are also used during startup and for alerts. There are no separate GPS and mobile-network status indicators.</p><p><strong>Four lights do not always mean a full battery.</strong> First check whether the tracker has just restarted, is showing normal battery status or is charging.</p><h2 id="normal-battery-display" tabindex="-1">Normal battery display <a class="header-anchor" href="#normal-battery-display" aria-label="Permalink to &quot;Normal battery display&quot;">​</a></h2><p>A short status-button press normally shows the battery level briefly. The four indicators use these approximate bands:</p><table tabindex="0"><thead><tr><th>Battery level</th><th>Normal battery display</th></tr></thead><tbody><tr><td>Below 20%</td><td>First indicator flashes when showing status off charge</td></tr><tr><td>20% to below 40%</td><td>1 indicator</td></tr><tr><td>40% to below 60%</td><td>2 indicators</td></tr><tr><td>60% to below 80%</td><td>3 indicators</td></tr><tr><td>80% or more</td><td>4 indicators</td></tr></tbody></table><p>These bands apply to the normal battery display only. Startup, alerts and application-controlled patterns can use the same lights for a different reason. Four lights are not an exact 100% reading.</p><figure><img src="'+e+'" alt="Four-light battery display: below 20 percent the first light flashes off charge; at least 20, 40, 60 and 80 percent shows one, two, three and four lights respectively." tabindex="0"><figcaption>Four-light battery display: below 20 percent the first light flashes off charge; at least 20, 40, 60 and 80 percent shows one, two, three and four lights respectively.</figcaption></figure><h2 id="charging" tabindex="-1">Charging <a class="header-anchor" href="#charging" aria-label="Permalink to &quot;Charging&quot;">​</a></h2><ul><li>Below about 95%, the highest lit battery indicator blinks, roughly one second on and one second off. At very low charge, the first indicator blinks.</li><li>At about 95% or above, the normal charging display becomes steady. This means a high charge level, not an exact 100% reading.</li><li>When unplugged and resting, the lights normally go out after any temporary status display finishes. A button press, startup or other activity can still light them.</li></ul><p>These are the standard battery-bar patterns. They are not the RGB charging colours used by RH2.</p><figure><img src="'+a+'" alt="Charging shown in two frames: at three bars the first two lights stay on, the third alternates on and off about every second, and the fourth stays off." tabindex="0"><figcaption>Charging shown in two frames: at three bars the first two lights stay on, the third alternates on and off about every second, and the fourth stays off.</figcaption></figure><p>The charger can also trigger a protection pattern that differs from the normal charging blink. If two lights keep flashing together or charging does not progress, contact <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">support</a> with a video and details of the charging accessory. Do not treat every flashing pattern as a battery reading.</p><h2 id="after-a-restart" tabindex="-1">After a restart <a class="header-anchor" href="#after-a-restart" aria-label="Permalink to &quot;After a restart&quot;">​</a></h2><p>Startup can light all four indicators or run a sequence across them. The exact sequence depends on the firmware and reset reason, so a photograph of the startup lights is not a fault diagnosis or a charge measurement.</p><p>Let the device finish starting, then check its latest successful communication in the app or portal. If updates do not resume, check charge, data plan and mobile coverage, then follow <a href="/docs/pr/40/faq/troubleshooting#why-is-my-tracker-not-transmitting">tracker troubleshooting</a>. Avoid repeated resets based only on the lights.</p><h2 id="other-patterns" tabindex="-1">Other patterns <a class="header-anchor" href="#other-patterns" aria-label="Permalink to &quot;Other patterns&quot;">​</a></h2><p>Alarms, custom applications and remote LED control can override the standard display. Use your application&#39;s instructions when it controls the lights. For an unfamiliar or persistent pattern, include the device ID, hardware revision if known, charging state and a short video when contacting support.</p><p>Choose another model in the <a href="/docs/pr/40/guides/leds">LED guide</a>.</p>',22)])])}const y=r(n,[["render",h]]);export{m as __pageData,y as default};
